class Solution {
public:
    vector<int> cheapestJump(vector<int>& coins, int maxJump) {
        int n = coins.size();
        if (n == 0 || coins[0] == -1 || coins[n - 1] == -1) {
            return {};
        }
        const long long INF = LLONG_MAX / 4;
        vector<long long> cost(n, INF);
        vector<int> next(n, -1);
        cost[n - 1] = coins[n - 1];
        for (int i = n - 2; i >= 0; --i) {
            if (coins[i] == -1) {
                continue;
            }
            for (int j = i + 1; j < n && j <= i + maxJump; ++j) {
                if (cost[j] == INF) {
                    continue;
                }
                long long candidate = coins[i] + cost[j];
                if (candidate < cost[i]) {
                    cost[i] = candidate;
                    next[i] = j;
                }
            }
        }
        if (cost[0] == INF) {
            return {};
        }
        vector<int> path;
        for (int i = 0; i != -1; i = next[i]) {
            path.push_back(i + 1);
        }
        return path;
    }
};
